  sunglass: (B, C, c) => { const r = B.ew * 1.28, y = B.eyeY + B.eh * 0.1; return `<g class="mp-glass">${[-1, 1].map((o) => { const cx = 50 + o * B.ex; const d = `M${mscP(cx - r, y - r * 0.55)}Q${mscP(cx, y - r * 0.72)} ${mscP(cx + r, y - r * 0.55)}Q${mscP(cx + r * 1.02, y + r * 0.55)} ${mscP(cx, y + r * 0.8)}Q${mscP(cx - r * 1.02, y + r * 0.55)} ${mscP(cx - r, y - r * 0.55)}Z`; return `<path d="${d}" fill="#1E2430" fill-opacity=".86" stroke="${c}" stroke-width=".5"/>` + mscLine(`M${mscP(cx - r * 0.6, y - r * 0.2)}l${mscF(r * 0.55)} ${mscF(-r * 0.3)}`, '#fff', 0.45, 0.55) + mscLine(`M${mscP(cx + r * 0.1, y + r * 0.4)}l${mscF(r * 0.4)} ${mscF(-r * 0.25)}`, '#9AD0FF', 0.3, 0.5); }).join('')}${mscLine(`M${mscP(50 - B.ex + r, y - r * 0.4)}Q50 ${mscF(y - r * 0.75)} ${mscP(50 + B.ex - r, y - r * 0.4)}M${mscP(50 - B.ex - r, y - r * 0.45)}L${mscP(50 - B.fw * 1.02, y - 1)}M${mscP(50 + B.ex + r, y - r * 0.45)}L${mscP(50 + B.fw * 1.02, y - 1)}`, c, 0.6)}</g>`; },
