  goggles: (B, C, c) => { const U = (u) => 50 + u * B.fw, V = (v) => B.crown + B.vm(v) * B.H, y = V(0.2), r = B.ew * 1.05; return mscLine(`M${mscP(U(-1.08), y + 0.6)}Q${mscP(50, y - 1.2)} ${mscP(U(1.08), y + 0.6)}`, mscS1(c), 0.9) + [-1, 1].map((o) => { const cx = 50 + o * B.ex * 0.95; return `<ellipse cx="${mscF(cx)}" cy="${mscF(y)}" rx="${mscF(r)}" ry="${mscF(r * 0.72)}" fill="#BFE6FF" fill-opacity=".75" stroke="${c}" stroke-width=".7"/>` + mscLine(`M${mscP(cx - r * 0.5, y - r * 0.15)}l${mscF(r * 0.5)} ${mscF(-r * 0.3)}`, '#fff', 0.4, 0.8); }).join('') + mscLine(`M${mscP(50 - B.ex * 0.95 + r, y)}L${mscP(50 + B.ex * 0.95 - r, y)}`, c, 0.6); },
